import hygCatalogData from './data/hygCatalog.json'
import type { HygStarRecord } from './starTypes'

/**
 * Validates a single record's type/range at load time. The build script
 * (scripts/build-hyg-catalog.mjs) already filters when generating the bundled
 * JSON, but CLAUDE.md's Security Baseline calls for validating external data
 * where it's consumed too, in case the committed file is ever hand-edited,
 * regenerated by a modified script, or otherwise corrupted.
 */
function isValidHygStarRecord(record: unknown): record is HygStarRecord {
  if (typeof record !== 'object' || record === null) return false
  const { id, raHours, decDegrees, magnitude, colorIndex, properName } =
    record as Record<string, unknown>

  return (
    typeof id === 'number' &&
    Number.isFinite(id) &&
    typeof raHours === 'number' &&
    raHours >= 0 &&
    raHours < 24 &&
    typeof decDegrees === 'number' &&
    decDegrees >= -90 &&
    decDegrees <= 90 &&
    typeof magnitude === 'number' &&
    Number.isFinite(magnitude) &&
    (colorIndex === null ||
      (typeof colorIndex === 'number' && Number.isFinite(colorIndex))) &&
    (properName === null || typeof properName === 'string')
  )
}

let cachedCatalog: HygStarRecord[] | null = null
let cachedStarsById: Map<number, HygStarRecord> | null = null

/** Loads the pre-filtered HYG Database catalog (see DECISIONS.md D013). */
export function loadHygStarCatalog(): HygStarRecord[] {
  if (cachedCatalog === null) {
    cachedCatalog = (hygCatalogData as unknown[]).filter(isValidHygStarRecord)
  }
  return cachedCatalog
}

/**
 * Looks up a single catalog record by its HYG id (Task 5: resolving a
 * tap/click-selected star, via StarData.hygId, back to its real magnitude,
 * color index, and proper name). Backed by a cached id->record map rather
 * than a linear scan: besides Task 5's tap-selection use, Task 6's
 * `Starfield.tsx` also calls this from inside a label-sort comparator that
 * reruns on every date/location recompute (up to ~15Hz during playback while
 * a constellation is selected), so an O(n) scan over the ~8,900-star catalog
 * per comparison is not "once per selection" in practice.
 */
export function findHygStarById(id: number): HygStarRecord | undefined {
  if (cachedStarsById === null) {
    cachedStarsById = new Map(
      loadHygStarCatalog().map((star) => [star.id, star]),
    )
  }
  return cachedStarsById.get(id)
}
